/* TIPTEKNO'26 — CGR web presentation.
 * Every number comes from window.DATA (assets/js/data.js, generated by
 * Scripts/06_presentation_assets.py). Works offline and from file://.
 */
(() => {
  'use strict';
  const D = window.DATA;
  if (!D) { document.body.innerHTML = '<p style="padding:40px;font-family:sans-serif">assets/js/data.js is missing.</p>'; return; }

  // ------------------------------------------------------------------ constants
  const GEN = D.genera;
  const GC = { Alphacoronavirus: '#0a84ff', Betacoronavirus: '#ff9f0a', Gammacoronavirus: '#30b0c7', Deltacoronavirus: '#bf5af2', 'SARS-CoV-2': '#ff375f' };
  const NUCC = { A: '#30d158', C: '#0a84ff', G: '#ffcc00', T: '#ff453a' };
  const CORNER = { A: [0, 0], C: [0, 1], G: [1, 1], T: [1, 0] };   // x right, y up
  const SHORT = {
    tr: { Alphacoronavirus: 'Alfa', Betacoronavirus: 'Beta', Gammacoronavirus: 'Gama', Deltacoronavirus: 'Delta' },
    en: { Alphacoronavirus: 'Alpha', Betacoronavirus: 'Beta', Gammacoronavirus: 'Gamma', Deltacoronavirus: 'Delta' },
  };
  const EX = {
    tr: { Alphacoronavirus: 'İnsan soğuk algınlığı (229E, NL63), domuz salgın ishali (PEDV)',
          Betacoronavirus: 'SARS, MERS, insan koronavirüsleri OC43 ve HKU1',
          Gammacoronavirus: 'Tavuk bulaşıcı bronşiti (IBV)',
          Deltacoronavirus: 'Domuz deltakoronavirüsü (PDCoV)' },
    en: { Alphacoronavirus: 'Human common cold (229E, NL63), porcine epidemic diarrhoea (PEDV)',
          Betacoronavirus: 'SARS, MERS, human coronaviruses OC43 and HKU1',
          Gammacoronavirus: 'Avian infectious bronchitis (IBV)',
          Deltacoronavirus: 'Porcine deltacoronavirus (PDCoV)' },
  };
  D.derived = {
    total: GEN.reduce((s, g) => s + D.counts[g], 0),
    correct: D.confusion.reduce((s, row, i) => s + row[i], 0),
  };
  const REDUCED = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  const $ = (id) => document.getElementById(id);
  const params = new URLSearchParams(location.search);
  const isPresenter = params.has('presenter');

  // ------------------------------------------------------------------ language & numbers
  let lang = 'tr';
  try { const s = localStorage.getItem('cgr-lang'); if (s === 'tr' || s === 'en') lang = s; } catch (e) { /* storage blocked */ }
  if (params.get('lang') === 'en' || params.get('lang') === 'tr') lang = params.get('lang');
  document.documentElement.dataset.lang = lang;
  document.documentElement.lang = lang;

  const nf = (v, dec = 0) => new Intl.NumberFormat(lang === 'tr' ? 'tr-TR' : 'en-US',
    { minimumFractionDigits: dec, maximumFractionDigits: dec }).format(v);
  const pct = (v, dec = 1) => (lang === 'tr' ? '%' + nf(v, dec) : nf(v, dec) + '%');
  const T = (tr, en) => (lang === 'en' ? en : tr);
  const nameOf = (sc) => (lang === 'en' && sc.dataset.nameEn ? sc.dataset.nameEn : sc.dataset.name);
  const getPath = (o, p) => p.split('.').reduce((a, k) => (a == null ? a : a[k]), o);
  const mmss = (sec) => { sec = Math.max(0, Math.round(sec)); return String(Math.floor(sec / 60)).padStart(2, '0') + ':' + String(sec % 60).padStart(2, '0'); };
  const lcg = (seed) => { let s = seed >>> 0; return () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296; };

  function fmtNumEl(el, v) {
    const dec = +(el.dataset.dec || 0);
    el.textContent = el.dataset.fmt === 'pct' ? pct(v, dec) : nf(v, dec);
  }
  function countUp(el, target) {
    cancelAnimationFrame(el._raf);
    if (REDUCED) { fmtNumEl(el, target); return; }
    const t0 = performance.now(), dur = 900;
    const tick = (t) => {
      const p = Math.min(1, (t - t0) / dur), e = 1 - Math.pow(1 - p, 3);
      fmtNumEl(el, target * e);
      if (p < 1) el._raf = requestAnimationFrame(tick); else fmtNumEl(el, target);
    };
    el._raf = requestAnimationFrame(tick);
  }
  function setNums(sc) {
    sc.querySelectorAll('.num').forEach((el) => {
      const v = getPath(D, el.dataset.num);
      if (typeof v !== 'number') { el.textContent = v == null ? '' : String(v); return; }
      const b = el.closest('.b'), vis = !b || b.classList.contains('in');
      if (vis && !el._done) { el._done = true; countUp(el, v); }
      else if (!vis) { el._done = false; cancelAnimationFrame(el._raf); fmtNumEl(el, 0); }
    });
  }

  // ------------------------------------------------------------------ drawing helpers
  const MAGMA = [[0, 0, 0, 4], [.13, 28, 16, 68], [.25, 79, 18, 123], [.38, 129, 37, 129], [.5, 181, 54, 122],
                 [.63, 229, 80, 100], [.75, 251, 135, 97], [.88, 254, 194, 135], [1, 252, 253, 191]];
  function magma(t) {
    t = Math.max(0, Math.min(1, t));
    for (let i = 1; i < MAGMA.length; i++) {
      if (t <= MAGMA[i][0]) {
        const a = MAGMA[i - 1], b = MAGMA[i], f = (t - a[0]) / (b[0] - a[0]);
        return [a[1] + f * (b[1] - a[1]), a[2] + f * (b[2] - a[2]), a[3] + f * (b[3] - a[3])];
      }
    }
    return MAGMA[MAGMA.length - 1].slice(1);
  }
  function fit(c) {
    const r = c.getBoundingClientRect(), dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.max(2, Math.round(r.width * dpr)), h = Math.max(2, Math.round(r.height * dpr));
    if (c.width !== w || c.height !== h) { c.width = w; c.height = h; }
    const ctx = c.getContext('2d'); ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.globalAlpha = 1;
    return { ctx, w, h, dpr };
  }
  function drawHeat(c, vals, side, map) {
    const { ctx, w, h } = fit(c);
    const off = document.createElement('canvas'); off.width = side; off.height = side;
    const octx = off.getContext('2d'), img = octx.createImageData(side, side);
    for (let i = 0; i < side * side; i++) {
      const [r, g, b] = magma(map ? map(vals[i]) : vals[i]);
      img.data[4 * i] = r; img.data[4 * i + 1] = g; img.data[4 * i + 2] = b; img.data[4 * i + 3] = 255;
    }
    octx.putImageData(img, 0, 0);
    ctx.imageSmoothingEnabled = false; ctx.clearRect(0, 0, w, h); ctx.drawImage(off, 0, 0, w, h);
  }

  // chaos game: point after each letter (ambiguous letters restart at the centre)
  const ptsCache = new Map();
  function cgrPoints(seq) {
    if (ptsCache.has(seq)) return ptsCache.get(seq);
    const out = new Float32Array(seq.length * 2); let x = 0.5, y = 0.5, n = 0;
    for (let i = 0; i < seq.length; i++) {
      const c = CORNER[seq[i]];
      if (!c) { x = 0.5; y = 0.5; continue; }
      x = (x + c[0]) / 2; y = (y + c[1]) / 2; out[n++] = x; out[n++] = y;
    }
    const r = out.subarray(0, n); ptsCache.set(seq, r); return r;
  }
  function drawCGR(c, pts, opt) {
    cancelAnimationFrame(c._raf);
    const { ctx, w, h, dpr } = fit(c);
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = opt.color; ctx.globalAlpha = opt.alpha;
    const s = Math.max(1, (opt.size || 1) * dpr), total = pts.length / 2;
    let i = 0;
    const run = () => {
      const end = opt.perFrame && !REDUCED ? Math.min(total, i + opt.perFrame) : total;
      for (; i < end; i++) ctx.fillRect(pts[2 * i] * w - s / 2, (1 - pts[2 * i + 1]) * h - s / 2, s, s);
      if (i < total) c._raf = requestAnimationFrame(run); else { ctx.globalAlpha = 1; if (opt.onDone) opt.onDone(); }
    };
    run();
  }
  // k-mer counts in the chaos-game layout: the LAST letter read picks the coarsest quadrant
  function fcgrCells(seq, k) {
    const side = 1 << k, M = new Float64Array(side * side); let tot = 0;
    for (let i = k - 1; i < seq.length; i++) {
      let x = 0, y = 0, ok = true;
      for (let j = 0; j < k; j++) {
        const cc = CORNER[seq[i - j]];
        if (!cc) { ok = false; break; }
        x = (x << 1) | cc[0]; y = (y << 1) | cc[1];
      }
      if (!ok) continue;
      M[(side - 1 - y) * side + x]++; tot++;
    }
    for (let i = 0; i < M.length; i++) M[i] /= tot;
    return M;
  }
  function cellWord(row, col, k) {
    const side = 1 << k, y = side - 1 - row, x = col; let addr = '';
    for (let p = 0; p < k; p++) {
      const xb = (x >> (k - 1 - p)) & 1, yb = (y >> (k - 1 - p)) & 1;
      addr += xb ? (yb ? 'G' : 'T') : (yb ? 'C' : 'A');
    }
    return addr.split('').reverse().join('');
  }

  // ------------------------------------------------------------------ scene builders
  let sel = 0;                                   // genome shown in the CGR / FCGR scenes

  function buildTicker() {
    const seq = D.demo[0].seq.slice(0, 1200);
    let html = '';
    for (let i = 0; i < seq.length; i++) {
      html += '<span class="n' + seq[i] + '">' + seq[i] + '</span>';
      if (i % 10 === 9) html += ' ';
    }
    $('ticker').innerHTML = html + html;
    document.querySelectorAll('.acc0').forEach((e) => { e.textContent = D.demo[0].acc; });
  }
  function buildAlign() {
    const ref = D.demo[0].seq.slice(200, 228).split('');
    const qry = ref.slice();
    const swap = { A: 'G', G: 'A', C: 'T', T: 'C' };
    [5, 13, 22].forEach((i) => { qry[i] = swap[qry[i]] || 'A'; });
    qry[17] = '–';
    const tr = lang === 'tr';
    const cell = (ch, i, row) => {
      if (row === 'bar') return '<i class="bar">' + (qry[i] === ref[i] ? '|' : '&nbsp;') + '</i>';
      const cls = qry[i] === '–' ? 'gap' : (qry[i] !== ref[i] ? 'mm' : '');
      return '<i class="' + cls + '">' + ch + '</i>';
    };
    $('alignViz').innerHTML =
      '<div class="alrow"><span class="lab">' + (tr ? 'Yeni dizi' : 'Query') + '</span>' + qry.map((c, i) => cell(c, i, 'q')).join('') + '</div>' +
      '<div class="alrow"><span class="lab"></span>' + qry.map((c, i) => cell(c, i, 'bar')).join('') + '</div>' +
      '<div class="alrow"><span class="lab">' + (tr ? 'Referans' : 'Reference') + '</span>' + ref.map((c, i) => cell(c, i, 'r')).join('') + '</div>';
  }
  function buildChips() {
    const box = $('chips'); box.innerHTML = '';
    D.demo.forEach((g, idx) => {
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'chip' + (idx === sel ? ' on' : '');
      const fam = g.genus === 'SARS-CoV-2' ? 'Beta' : SHORT[lang][g.genus];
      b.innerHTML = '<i style="background:' + GC[g.genus] + '"></i>' + g.name + ' · ' + fam;
      b.addEventListener('click', (e) => { e.stopPropagation(); sel = idx; buildChips(); renderCGR(true); cgrShown = true; });
      box.appendChild(b);
    });
    updateCgrCaption();
  }
  function updateCgrCaption() {
    const g = D.demo[sel];
    $('cgrCaption').textContent = 'GenBank ' + g.acc + ' · ' + g.name + ' · ' + nf(g.seq.length) + (lang === 'tr' ? ' harf' : ' letters');
  }
  function buildGenusGrid() {
    $('genusGrid').innerHTML = GEN.map((g) =>
      '<div class="gcard" style="--c:' + GC[g] + '"><div class="n num" data-num="counts.' + g + '"></div>' +
      '<div class="gname">' + g + '</div><div class="ex">' + EX[lang][g] + '</div></div>').join('');
  }
  function buildSigGrid() {
    $('sigGrid').innerHTML = GEN.map((g) => '<figure style="--c:' + GC[g] + '"><canvas></canvas><figcaption>' + g + '</figcaption></figure>').join('');
  }
  function drawSigs() { document.querySelectorAll('#sigGrid canvas').forEach((c, i) => drawHeat(c, D.sig6[GEN[i]], 64)); }
  function buildLegend() {
    $('pcaLegend').innerHTML = GEN.map((g) => '<span><i style="background:' + GC[g] + '"></i><em>' + g + '</em></span>').join('');
  }
  function buildCM() {
    const S = SHORT[lang];
    let html = '<caption>' + (lang === 'tr' ? 'Satır: gerçek aile · Sütun: tahmin' : 'Rows: true family · Columns: predicted') + '</caption>' +
      '<tr><th></th>' + GEN.map((g) => '<th>' + S[g] + '</th>').join('') + '</tr>';
    D.confusion.forEach((row, i) => {
      html += '<tr><th class="row">' + S[GEN[i]] + '</th>' +
        row.map((v, j) => '<td class="' + (i === j ? 'diag' : (v > 0 ? 'err' : '')) + '">' + nf(v) + '</td>').join('') + '</tr>';
    });
    $('cmTable').innerHTML = html;
  }
  function buildKrow() {
    const cv = D.cv['SVM-linear'];
    $('krow').innerHTML = [3, 4, 5, 6, 7].map((k) =>
      '<div class="kcard' + (k === 3 ? ' hl' : '') + '"><div class="k">k = ' + k + '</div>' +
      '<div class="acc">' + pct(cv[k], 1) + '</div><div class="dim">' + nf(Math.pow(4, k)) + (lang === 'tr' ? ' sayı' : ' numbers') + '</div></div>').join('');
  }
  function buildSig3() {
    $('sig3').innerHTML = GEN.map((g) => '<figure style="--c:' + GC[g] + '"><canvas></canvas><figcaption>' + SHORT[lang][g] + '</figcaption></figure>').join('') +
      '<p class="note">' + (lang === 'tr'
        ? 'Dört ailenin 64 sayılık imzası (k = 3): her kare, bir üç harflik kelimenin sıklığı.'
        : 'Each family’s 64-number signature (k = 3): every square is how often one three-letter word occurs.') + '</p>';
  }
  function drawSig3() {
    let mx = -Infinity, mn = Infinity;
    GEN.forEach((g) => D.sig3[g].forEach((v) => { mx = Math.max(mx, v); mn = Math.min(mn, v); }));
    document.querySelectorAll('#sig3 canvas').forEach((c, i) => drawHeat(c, D.sig3[GEN[i]], 8, (v) => (v - mn) / (mx - mn)));
  }
  function buildSplits() {
    const SPC = ['#64d2ff', '#ffcc00', '#30d158', '#ff9f0a', '#bf5af2', '#ff6482'];
    const tr = lang === 'tr';
    const dot = (i, warn) => '<span class="sp' + (warn ? ' warn' : '') + '" style="background:' + SPC[i] + '"></span>';
    const rnd = { train: [0, 0, 1, 2, 2, 3, 4, 5, 5], test: [0, 2, 5] };
    const grp = { train: [0, 0, 1, 1, 2, 2, 3, 3], test: [4, 4, 5] };
    const seen = new Set(rnd.train);
    const row = (lab, arr, warnSet) => '<div class="srow"><span class="lab">' + lab + '</span>' + arr.map((i) => dot(i, warnSet && warnSet.has(i))).join('') + '</div>';
    const T = tr ? 'Eğitim' : 'Training', E = 'Test';
    $('splits').innerHTML =
      '<div class="split"><h3>' + (tr ? 'Rastgele bölme' : 'Random split') + '</h3>' + row(T, rnd.train) + row(E, rnd.test, seen) +
      '<p class="verdict bad"><b>' + (tr ? 'Aynı tür iki tarafta.' : 'The same species on both sides.') + '</b> ' +
      (tr ? 'Model yalnızca kopyayı tanıyor olabilir.' : 'The model may just be recognising a copy.') + '</p></div>' +
      '<div class="split"><h3>' + (tr ? 'Tür-farkında bölme' : 'Species-aware split') + '</h3>' + row(T, grp.train) + row(E, grp.test) +
      '<p class="verdict good"><b>' + (tr ? 'Her tür tek tarafta.' : 'Each species on one side only.') + '</b> ' +
      (tr ? 'Test gerçekten yeni türlerden.' : 'The test holds genuinely new species.') + '</p></div>';
  }
  function buildBins() {
    $('bins').innerHTML = GEN.map((g) => '<div style="--c:' + GC[g] + '">' + g + '</div>').join('');
  }
  function buildUrls() {
    $('pagesUrl').textContent = D.urls.pages.replace(/^https?:\/\//, '').replace(/\/$/, '');
    $('repoUrl').textContent = D.urls.repo.replace(/^https?:\/\//, '');
  }

  // ------------------------------------------------------------------ fragment chart (SVG)
  function buildFrag() {
    const svg = $('fragChart'), F = D.fragment, tr = lang === 'tr';
    const W = 1000, H = 470, m = { l: 86, r: 40, t: 18, b: 74 };
    const xs = F.lengths.map((v) => (v === 'full' ? 40000 : v));
    const L0 = Math.log10(250), L1 = Math.log10(40000);
    const lx = (v) => m.l + (Math.log10(v) - L0) / (L1 - L0) * (W - m.l - m.r);
    const ly = (v) => m.t + (100 - v) / 60 * (H - m.t - m.b);
    let g = '';
    [40, 60, 80, 100].forEach((v) => {
      g += '<line class="grid" x1="' + m.l + '" x2="' + (W - m.r) + '" y1="' + ly(v) + '" y2="' + ly(v) + '"/>' +
           '<text x="' + (m.l - 14) + '" y="' + (ly(v) + 6) + '" text-anchor="end">' + pct(v, 0) + '</text>';
    });
    g += '<line class="axis" x1="' + m.l + '" x2="' + (W - m.r) + '" y1="' + ly(40) + '" y2="' + ly(40) + '"/>';
    const ticks = [[250, '250'], [500, '500'], [1000, '1.000'], [2000, '2.000'], [5000, '5.000'], [10000, '10.000'], [40000, tr ? 'tam genom' : 'full genome']];
    ticks.forEach(([v, t]) => {
      const lab = tr ? t : t.replace(/\./g, ',');
      g += '<text x="' + lx(v) + '" y="' + (H - m.b + 32) + '" text-anchor="middle">' + lab + '</text>';
    });
    g += '<text x="' + ((m.l + W - m.r) / 2) + '" y="' + (H - 6) + '" text-anchor="middle">' +
         (tr ? 'Test parçasının uzunluğu (harf, log ölçek) · model tam genomla eğitildi' : 'Test fragment length (letters, log scale) · model trained on full genomes') + '</text>';
    g += '<line class="grid" x1="' + lx(1000) + '" x2="' + lx(1000) + '" y1="' + ly(100) + '" y2="' + ly(40) + '"/>';
    const path = (arr) => arr.map((v, i) => (i ? 'L' : 'M') + lx(xs[i]).toFixed(1) + ',' + ly(v).toFixed(1)).join(' ');
    g += '<path id="s3" class="ser" stroke="#8e8e93" d="' + path(F.k3) + '"/>';
    g += '<path id="s5" class="ser" stroke="#0071e3" d="' + path(F.k5) + '"/>';
    F.k3.forEach((v, i) => { g += '<circle class="pt p3 hide" cx="' + lx(xs[i]) + '" cy="' + ly(v) + '" r="7" fill="#8e8e93"/>'; });
    F.k5.forEach((v, i) => { g += '<circle class="pt p5 hide" cx="' + lx(xs[i]) + '" cy="' + ly(v) + '" r="7" fill="#0071e3"/>'; });
    const i1 = xs.indexOf(1000);
    g += '<text class="lbl l3 hide" x="' + (lx(1000) + 16) + '" y="' + (ly(F.k3[i1]) + 34) + '" style="fill:#6e6e73">k = 3 · ' + pct(F.k3[i1], 1) + '</text>';
    g += '<text class="lbl l5 hide" x="' + (lx(1000) - 16) + '" y="' + (ly(F.k5[i1]) - 20) + '" text-anchor="end" style="fill:#0071e3">k = 5 · ' + pct(F.k5[i1], 1) + '</text>';
    svg.innerHTML = g;
    ['s3', 's5'].forEach((id) => {
      const p = svg.querySelector('#' + id), len = p.getTotalLength();
      p.style.transition = 'none'; p.style.strokeDasharray = len; p.style.strokeDashoffset = len; p.dataset.len = len;
    });
  }
  function fragStep(s) {
    const svg = $('fragChart');
    const set = (id, on) => {
      const p = svg.querySelector('#' + id); if (!p) return;
      p.getBoundingClientRect();                              // commit the start state before animating
      p.style.transition = ''; p.style.strokeDashoffset = on ? 0 : p.dataset.len;
    };
    set('s3', s >= 1); set('s5', s >= 2);
    svg.querySelectorAll('.p3,.l3').forEach((e) => e.classList.toggle('hide', s < 1));
    svg.querySelectorAll('.p5,.l5').forEach((e) => e.classList.toggle('hide', s < 2));
  }

  // ------------------------------------------------------------------ live scenes
  function startBg(instant) {
    drawCGR($('bgcgr'), cgrPoints(D.demo[0].seq), { color: '#5e5ce6', alpha: 0.2, size: 2.6, perFrame: instant ? 0 : 60 });
  }

  // rule: the first letters, one click each, then a 500-letter fast-forward
  const RULE_FAST = 500, STRIP = 18;
  let ruleLast = -1;
  function ruleStrip(nDone, s) {
    const strip = $('ruleStrip'), seq = D.demo[0].seq;
    if (!strip._built) {
      strip.innerHTML = seq.slice(0, STRIP).split('').map((ch) => '<i class="n' + ch + '">' + ch + '</i>').join('') + '<span class="more"></span>';
      strip._built = true;
    }
    strip.querySelectorAll('i').forEach((el, i) => {
      el.classList.toggle('done', i < nDone);
      el.classList.toggle('now', s < 8 && i === nDone - 1);
    });
    strip.querySelector('.more').textContent = s >= 8
      ? (lang === 'tr' ? '… ve ' + nf(RULE_FAST - STRIP) + ' harf daha' : '… and ' + nf(RULE_FAST - STRIP) + ' more')
      : '…';
  }
  function ruleRender(s, animate) {
    const c = $('ruleCanvas'); cancelAnimationFrame(c._raf);
    const seq = D.demo[0].seq;
    const P = [[0.5, 0.5]];
    for (let i = 0; i < RULE_FAST; i++) {
      const cc = CORNER[seq[i]], [x, y] = P[P.length - 1];
      P.push(cc ? [(x + cc[0]) / 2, (y + cc[1]) / 2] : [0.5, 0.5]);
    }
    const nDone = s >= 8 ? RULE_FAST : Math.max(0, s - 1);
    ruleStrip(nDone, s);
    const { ctx, w, h, dpr } = fit(c);
    const X = (p) => p[0] * w, Y = (p) => (1 - p[1]) * h;
    const ring = () => {
      ctx.strokeStyle = 'rgba(255,255,255,.75)'; ctx.lineWidth = 2 * dpr;
      ctx.beginPath(); ctx.arc(X(P[0]), Y(P[0]), 10 * dpr, 0, 7); ctx.stroke();
    };
    const dot = (p, col, r) => {
      ctx.fillStyle = col; ctx.beginPath(); ctx.arc(X(p), Y(p), r, 0, 7); ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,.55)'; ctx.lineWidth = 1.5 * dpr; ctx.stroke();
    };
    const staticUpTo = (n) => {
      ctx.clearRect(0, 0, w, h); ring();
      ctx.strokeStyle = 'rgba(255,255,255,.28)'; ctx.lineWidth = 1.6 * dpr; ctx.beginPath();
      for (let j = 0; j <= n; j++) { if (j === 0) ctx.moveTo(X(P[0]), Y(P[0])); else ctx.lineTo(X(P[j]), Y(P[j])); }
      ctx.stroke();
      for (let j = 1; j <= n; j++) dot(P[j], NUCC[seq[j - 1]] || '#fff', 8 * dpr);
    };
    if (s < 1) { ctx.clearRect(0, 0, w, h); return; }
    if (s >= 8) {                                             // fast-forward 500 letters
      ctx.clearRect(0, 0, w, h); ring();
      let j = 1;
      const run = () => {
        const end = animate && !REDUCED ? Math.min(RULE_FAST, j + 5) : RULE_FAST;
        for (; j <= end; j++) { ctx.fillStyle = NUCC[seq[j - 1]] || '#fff'; ctx.globalAlpha = 0.9; ctx.beginPath(); ctx.arc(X(P[j]), Y(P[j]), 2.6 * dpr, 0, 7); ctx.fill(); }
        ctx.globalAlpha = 1;
        if (j <= RULE_FAST) c._raf = requestAnimationFrame(run);
      };
      run();
      return;
    }
    if (!animate || nDone === 0 || REDUCED) { staticUpTo(nDone); return; }
    const a = P[nDone - 1], b = P[nDone], letter = seq[nDone - 1], corner = CORNER[letter] || [0.5, 0.5];
    const t0 = performance.now(), dur = 750;
    const frame = (t) => {
      const p = Math.min(1, (t - t0) / dur), e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      staticUpTo(nDone - 1);
      ctx.setLineDash([7 * dpr, 7 * dpr]); ctx.strokeStyle = NUCC[letter]; ctx.globalAlpha = 0.6; ctx.lineWidth = 2 * dpr;
      ctx.beginPath(); ctx.moveTo(X(a), Y(a)); ctx.lineTo(X(corner), Y(corner)); ctx.stroke();
      ctx.setLineDash([]); ctx.globalAlpha = 1;
      dot([a[0] + (b[0] - a[0]) * e, a[1] + (b[1] - a[1]) * e], NUCC[letter], 9 * dpr);
      if (p < 1) c._raf = requestAnimationFrame(frame); else staticUpTo(nDone);
    };
    c._raf = requestAnimationFrame(frame);
  }

  let cgrShown = false;
  function renderCGR(animate) {
    const g = D.demo[sel];
    drawCGR($('cgrCanvas'), cgrPoints(g.seq), { color: '#7fd3ff', alpha: 0.6, size: 1.6, perFrame: animate ? 240 : 0 });
    updateCgrCaption();
  }
  function clearCanvas(id) { const c = $(id); cancelAnimationFrame(c._raf); const { ctx, w, h } = fit(c); ctx.clearRect(0, 0, w, h); }

  function renderFCGR(s) {
    const c = $('fcgrCanvas'), g = D.demo[sel];
    drawCGR(c, cgrPoints(g.seq), { color: '#7fd3ff', alpha: 0.3, size: 1.1, perFrame: 0 });
    const k = Math.min(3, s);
    if (k < 1) return;
    const { ctx, w, h, dpr } = fit(c);
    const side = 1 << k, M = fcgrCells(g.seq, k);
    let mx = 0; for (let i = 0; i < M.length; i++) mx = Math.max(mx, M[i]);
    const cw = w / side, ch = h / side;
    for (let r = 0; r < side; r++) for (let q = 0; q < side; q++) {
      const v = M[r * side + q] / mx, [R, G, B] = magma(0.12 + 0.86 * v);
      ctx.fillStyle = 'rgba(' + (R | 0) + ',' + (G | 0) + ',' + (B | 0) + ',.8)';
      ctx.fillRect(q * cw, r * ch, cw, ch);
    }
    ctx.strokeStyle = 'rgba(255,255,255,.4)'; ctx.lineWidth = Math.max(1, dpr);
    for (let i = 1; i < side; i++) {
      ctx.beginPath(); ctx.moveTo(i * cw, 0); ctx.lineTo(i * cw, h); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, i * ch); ctx.lineTo(w, i * ch); ctx.stroke();
    }
    if (k <= 2) {
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      const f1 = Math.round(cw * (k === 1 ? 0.15 : 0.19)), f2 = Math.round(f1 * 0.62);
      for (let r = 0; r < side; r++) for (let q = 0; q < side; q++) {
        const v = M[r * side + q], light = magma(0.12 + 0.86 * v / mx);
        const lum = 0.2126 * light[0] + 0.7152 * light[1] + 0.0722 * light[2];
        ctx.fillStyle = lum > 150 ? '#1d1d1f' : '#ffffff';
        ctx.font = '700 ' + f1 + 'px ' + getComputedStyle(document.body).getPropertyValue('--mono');
        ctx.fillText(cellWord(r, q, k), (q + 0.5) * cw, (r + 0.5) * ch - f2 * 0.55);
        ctx.font = '500 ' + f2 + 'px ' + getComputedStyle(document.body).getPropertyValue('--sans');
        ctx.fillText(pct(v * 100, 1), (q + 0.5) * cw, (r + 0.5) * ch + f1 * 0.62);
      }
    }
  }

  function drawPCA(animate) {
    const c = $('pcaCanvas'); cancelAnimationFrame(c._raf);
    const { ctx, w, h, dpr } = fit(c); ctx.clearRect(0, 0, w, h);
    const pad = 0.07, pts = D.pca, rnd = lcg(11);
    const order = pts.map((_, i) => i);
    for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
    const r = 3.4 * dpr; let i = 0;
    const run = () => {
      const end = animate && !REDUCED ? Math.min(pts.length, i + 24) : pts.length;
      for (; i < end; i++) {
        const [x, y, gi] = pts[order[i]];
        ctx.globalAlpha = 0.78; ctx.fillStyle = GC[GEN[gi]];
        ctx.beginPath(); ctx.arc((pad + x * (1 - 2 * pad)) * w, (pad + (1 - y) * (1 - 2 * pad)) * h, r, 0, 7); ctx.fill();
      }
      ctx.globalAlpha = 1;
      if (i < pts.length) c._raf = requestAnimationFrame(run);
    };
    run();
  }

  function fallRender(s, instant) {
    const c = $('fallCanvas'), cnt = $('fallCount'); cancelAnimationFrame(c._raf);
    const { ctx, w, h, dpr } = fit(c);
    const nb = D.novel.beta, binW = w / 4, cols = 10;
    const gap = Math.min(binW / (cols + 1), h / 11), r = gap * 0.36;
    const tgt = (i) => [binW + binW / 2 + ((i % cols) - (cols - 1) / 2) * gap, h - gap / 2 - 2 * dpr - Math.floor(i / cols) * gap];
    const bins = () => {
      ctx.strokeStyle = 'rgba(255,255,255,.12)'; ctx.lineWidth = dpr;
      for (let b = 1; b < 4; b++) { ctx.beginPath(); ctx.moveTo(b * binW, h * 0.2); ctx.lineTo(b * binW, h); ctx.stroke(); }
    };
    const dot = (x, y) => { ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill(); };
    if (s < 1) { ctx.clearRect(0, 0, w, h); bins(); c._landed = false; cnt.textContent = nf(0); return; }
    if (c._landed || instant || REDUCED) {
      ctx.clearRect(0, 0, w, h); bins(); ctx.fillStyle = GC['SARS-CoV-2'];
      for (let i = 0; i < nb; i++) dot(...tgt(i));
      cnt.textContent = nf(nb); c._landed = true; return;
    }
    const rnd = lcg(7), starts = Array.from({ length: nb }, () => [w / 2 + (rnd() - 0.5) * w * 0.6, -r * 3]);
    const t0 = performance.now(), dur = 950, lag = 24;
    const run = (t) => {
      ctx.clearRect(0, 0, w, h); bins(); ctx.fillStyle = GC['SARS-CoV-2'];
      let landed = 0;
      for (let i = 0; i < nb; i++) {
        const p = Math.max(0, Math.min(1, (t - t0 - i * lag) / dur));
        if (p <= 0) continue;
        const ex = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
        const [sx, sy] = starts[i], [tx, ty] = tgt(i);
        dot(sx + (tx - sx) * ex, sy + (ty - sy) * p * p);
        if (p >= 1) landed++;
      }
      cnt.textContent = nf(landed);
      if (landed < nb) c._raf = requestAnimationFrame(run); else c._landed = true;
    };
    c._raf = requestAnimationFrame(run);
  }

  // ------------------------------------------------------------------ scene hooks
  const H = {
    title: { enter() { startBg(false); }, redraw() { startBg(true); }, leave() { cancelAnimationFrame($('bgcgr')._raf); } },
    rule: {
      step(s) { ruleRender(s, s === ruleLast + 1); ruleLast = s; },
      redraw(s) { ruleRender(s, false); },
      leave() { cancelAnimationFrame($('ruleCanvas')._raf); ruleLast = -1; },
    },
    cgr: {
      step(s) {
        if (s >= 1 && !cgrShown) { renderCGR(true); cgrShown = true; }
        else if (s === 0) { clearCanvas('cgrCanvas'); cgrShown = false; }
      },
      redraw(s) { if (s >= 1) renderCGR(false); },
      leave() { cancelAnimationFrame($('cgrCanvas')._raf); cgrShown = false; },
    },
    fcgr: { step(s) { renderFCGR(s); }, redraw(s) { renderFCGR(s); } },
    signatures: { enter() { drawSigs(); }, redraw() { drawSigs(); } },
    classifier: { enter() { drawPCA(true); }, redraw() { drawPCA(false); }, leave() { cancelAnimationFrame($('pcaCanvas')._raf); } },
    parsimony: { enter() { drawSig3(); }, redraw() { drawSig3(); } },
    unseen: {
      step(s) { fallRender(s, false); },
      redraw(s) { fallRender(s, true); },
      leave() { const c = $('fallCanvas'); cancelAnimationFrame(c._raf); c._landed = false; },
    },
    fragment: { enter() { buildFrag(); }, step(s) { fragStep(s); }, redraw(s) { fragStep(s); } },
  };

  // ------------------------------------------------------------------ deck navigation
  const scenes = Array.from(document.querySelectorAll('.scene'));
  const N = scenes.length;
  const times = scenes.map((s) => +s.dataset.time || 30);
  const cum = times.reduce((a, t, i) => { a.push((a[i - 1] || 0) + t); return a; }, []);
  let cur = -1, step = 0, timerStart = null;
  const maxStep = (i) => +scenes[i].dataset.steps || 0;

  // presenter link (BroadcastChannel, localStorage fallback)
  let bc = null;
  try { bc = new BroadcastChannel('cgr-deck'); } catch (e) { bc = null; }
  function post(msg) {
    if (bc) { try { bc.postMessage(msg); return; } catch (e) { /* fall through */ } }
    try { localStorage.setItem('cgr-deck-msg', JSON.stringify(Object.assign({ t: Date.now() }, msg))); } catch (e) { /* ignore */ }
  }
  function listen(fn) {
    if (bc) bc.onmessage = (e) => fn(e.data);
    window.addEventListener('storage', (e) => { if (e.key === 'cgr-deck-msg' && e.newValue) fn(JSON.parse(e.newValue)); });
  }

  function show(i, s, opt) {
    opt = opt || {};
    i = Math.max(0, Math.min(N - 1, i)); s = Math.max(0, Math.min(maxStep(i), s));
    const fresh = i !== cur;
    if (fresh && cur >= 0) {
      const old = scenes[cur], hk = H[old.id];
      if (hk && hk.leave) hk.leave();
      old.querySelectorAll('.num').forEach((e) => { e._done = false; });
    }
    cur = i; step = s;
    scenes.forEach((el, j) => el.classList.toggle('active', j === i));
    scenes[i].classList.add('seen');
    const sc = scenes[i];
    document.body.dataset.theme = sc.dataset.theme || 'light';
    sc.querySelectorAll('.b').forEach((b) => b.classList.toggle('in', +b.dataset.b <= s));
    setNums(sc);
    const hk = H[sc.id];
    if (hk) { if (fresh && hk.enter) hk.enter(s); if (hk.step) hk.step(s, fresh); }
    if (opt.user && !timerStart) timerStart = Date.now();
    updateChrome(); updateNotes();
    if (!opt.noHash) { try { history.replaceState(null, '', '#/' + (i + 1) + (s ? '.' + s : '')); } catch (e) { /* file:// */ } }
    post({ type: 'state', i: cur, s: step, timerStart });
  }
  // clicker/keyboard: reveal the next build; at the end of a section, glide to the next one
  let navLock = 0;
  function goTo(i, s, instant) {
    const changing = i !== cur;
    show(i, s, { user: true });
    if (changing) {
      navLock = Date.now() + (instant ? 300 : 1100);
      scenes[i].scrollIntoView({ behavior: instant || REDUCED ? 'auto' : 'smooth', block: 'start' });
    }
  }
  const next = () => { if (step < maxStep(cur)) show(cur, step + 1, { user: true }); else if (cur < N - 1) goTo(cur + 1, 0); };
  const prev = () => { if (step > 0) show(cur, step - 1, { user: true }); else if (cur > 0) goTo(cur - 1, maxStep(cur - 1)); };

  function updateChrome() {
    $('counter').textContent = String(cur + 1).padStart(2, '0') + ' / ' + String(N).padStart(2, '0');
    $('progress').firstElementChild.style.width = (N > 1 ? (cur + step / (maxStep(cur) + 1)) / (N - 1) * 100 : 100) + '%';
    $('langBtn').textContent = lang === 'tr' ? 'EN' : 'TR';
  }
  function paceHTML(i, startTs) {
    const el = startTs ? (Date.now() - startTs) / 1000 : 0, end = cum[i], start = end - times[i];
    const cls = el <= end + 5 ? 'pace-ok' : (el <= end + 30 ? 'pace-late' : 'pace-bad');
    return '<span class="' + cls + '">⏱ ' + mmss(el) + '</span> · plan ' + mmss(start) + '–' + mmss(end) + ' / ' + mmss(cum[N - 1]);
  }
  function updateNotes() {
    const p = $('notesPanel'); if (p.hidden || cur < 0) return;
    const sc = scenes[cur];
    $('npTitle').textContent = (cur + 1) + '/' + N + ' · ' + nameOf(sc) + (maxStep(cur) ? '  ·  ' + T('adım ', 'step ') + step + '/' + maxStep(cur) : '');
    $('npPace').innerHTML = paceHTML(cur, timerStart);
    $('npBody').innerHTML = sc.querySelector('.notes') ? sc.querySelector('.notes').innerHTML : '';
    $('npNext').textContent = cur < N - 1 ? T('Sonraki: ', 'Next: ') + nameOf(scenes[cur + 1]) : T('Son sahne', 'Last section');
  }

  function setLang(l) {
    lang = l;
    document.documentElement.dataset.lang = l; document.documentElement.lang = l;
    try { localStorage.setItem('cgr-lang', l); } catch (e) { /* ignore */ }
    buildLangDependent();
    document.querySelectorAll('.num').forEach((el) => {
      const v = getPath(D, el.dataset.num);
      if (typeof v === 'number' && el._done) { cancelAnimationFrame(el._raf); fmtNumEl(el, v); }
    });
    if (cur >= 0) {
      setNums(scenes[cur]);
      const hk = H[scenes[cur].id];
      if (scenes[cur].id === 'fragment') fragStep(step);
      else if (hk && hk.redraw) hk.redraw(step);
    }
    updateChrome(); updateNotes();
    post({ type: 'lang', lang: l });
  }
  function buildLangDependent() {
    buildAlign(); buildChips(); buildGenusGrid(); buildCM(); buildKrow(); buildSig3(); drawSig3(); buildSplits(); buildFrag();
    if ($('ruleStrip')._built) ruleStrip(step >= 8 && scenes[cur] && scenes[cur].id === 'rule' ? RULE_FAST : 0, scenes[cur] && scenes[cur].id === 'rule' ? step : 0);
  }

  function toggleFS() {
    const d = document, el = d.documentElement;
    if (!d.fullscreenElement && !d.webkitFullscreenElement) { (el.requestFullscreen || el.webkitRequestFullscreen).call(el); }
    else { (d.exitFullscreen || d.webkitExitFullscreen).call(d); }
  }
  function openPresenter() {
    const url = location.href.split('#')[0].split('?')[0] + '?presenter&lang=' + lang + location.hash;
    window.open(url, 'cgr-presenter', 'width=1000,height=720');
  }

  // ------------------------------------------------------------------ presenter window
  function initPresenter() {
    document.body.classList.add('presenter');
    const p = document.createElement('div'); p.id = 'presenter';
    p.innerHTML = '<div class="top"><div class="cur" id="pCur">…</div><div style="text-align:right"><div class="clock" id="pClock">00:00</div><div class="pace" id="pPace"></div></div></div>' +
      '<div class="body" id="pBody"><p>' + T('Ana sunum penceresi bekleniyor… (sunumu aynı tarayıcıda açık tutun)', 'Waiting for the main presentation window… (keep it open in the same browser)') + '</p></div>' +
      '<div class="bottom"><div id="pNext"></div><div><button id="pPrev" type="button"></button><button id="pNextBtn" type="button"></button></div></div>';
    document.body.appendChild(p);
    let st = { i: 0, s: 0, timerStart: null };
    const render = () => {
      const sc = scenes[st.i]; if (!sc) return;
      $('pCur').textContent = (st.i + 1) + '/' + N + ' · ' + nameOf(sc) + (maxStep(st.i) ? '  ·  ' + T('adım ', 'step ') + st.s + '/' + maxStep(st.i) : '');
      $('pBody').innerHTML = sc.querySelector('.notes') ? sc.querySelector('.notes').innerHTML : '';
      $('pNext').textContent = st.i < N - 1 ? T('Sonraki: ', 'Next: ') + nameOf(scenes[st.i + 1]) : T('Son sahne', 'Last section');
      $('pPrev').textContent = T('‹ Geri', '‹ Back'); $('pNextBtn').textContent = T('İleri ›', 'Next ›');
      tick();
    };
    const tick = () => {
      $('pClock').textContent = mmss(st.timerStart ? (Date.now() - st.timerStart) / 1000 : 0);
      $('pPace').innerHTML = paceHTML(st.i, st.timerStart);
    };
    $('pPrev').textContent = T('‹ Geri', '‹ Back'); $('pNextBtn').textContent = T('İleri ›', 'Next ›');
    listen((m) => {
      if (m && m.type === 'state') { st = m; render(); }
      else if (m && m.type === 'lang' && (m.lang === 'tr' || m.lang === 'en')) {   // follow the main window
        lang = m.lang; document.documentElement.dataset.lang = lang; document.documentElement.lang = lang; render();
      }
    });
    const cmd = (c) => post({ type: 'cmd', cmd: c });
    $('pPrev').onclick = () => cmd('prev'); $('pNextBtn').onclick = () => cmd('next');
    window.addEventListener('keydown', (e) => {
      if (['ArrowRight', 'ArrowDown', 'PageDown', ' ', 'Enter'].includes(e.key)) { e.preventDefault(); cmd('next'); }
      else if (['ArrowLeft', 'ArrowUp', 'PageUp', 'Backspace'].includes(e.key)) { e.preventDefault(); cmd('prev'); }
      else if (e.key === 't' || e.key === 'T') cmd('reset');
    });
    setInterval(tick, 1000);
    cmd('hello');
  }

  // ------------------------------------------------------------------ speaker-notes page (?notes)
  function initNotesDoc() {
    document.body.classList.add('notesmode'); document.body.dataset.theme = 'light';
    const doc = document.createElement('div'); doc.id = 'notesDoc';
    const other = lang === 'en' ? 'tr' : 'en';
    let html = '<h1>' + T('Konuşma notları', 'Speaker notes') + ' · TIPTEKNO\'26</h1><p class="sub">' +
      N + T(' sahne · toplam ', ' sections · total ') + mmss(cum[N - 1]) +
      T(' · [tıkla] = kumandaya bas', ' · [click] = press the clicker') + ' · ' + D.urls.pages.replace(/^https?:\/\//, '') +
      ' · <a href="?notes&lang=' + other + '">' + (other === 'en' ? 'English' : 'Türkçe') + '</a></p>';
    scenes.forEach((sc, i) => {
      html += '<section><h2>' + (i + 1) + '. ' + nameOf(sc) + '<span>' + mmss(cum[i] - times[i]) + '–' + mmss(cum[i]) + '</span></h2>' +
        (sc.querySelector('.notes') ? sc.querySelector('.notes').innerHTML : '') + '</section>';
    });
    doc.innerHTML = html; document.body.appendChild(doc);
  }

  // ------------------------------------------------------------------ boot
  if (isPresenter) { initPresenter(); return; }
  if (params.has('notes')) { initNotesDoc(); return; }

  if ('scrollRestoration' in history) history.scrollRestoration = 'manual';   // the URL decides where we are
  buildTicker(); buildSigGrid(); buildLegend(); buildBins(); buildUrls(); buildLangDependent();
  const parseHash = () => {
    const mm = location.hash.match(/#\/(\d+)(?:\.(\d+))?/);
    return mm ? [Math.max(0, Math.min(N - 1, +mm[1] - 1)), mm[2] ? +mm[2] : 0] : null;
  };
  const h0 = parseHash() || [0, 0];
  navLock = Date.now() + 400;
  show(h0[0], h0[1], { noHash: true });
  scenes[h0[0]].scrollIntoView({ behavior: 'auto', block: 'start' });
  window.addEventListener('hashchange', () => {           // typed or bookmarked #/n.s addresses
    const h = parseHash();
    if (h && (h[0] !== cur || h[1] !== step)) goTo(h[0], h[1], true);
  });

  // free scrolling (mouse, trackpad, touch): the section crossing the middle of the screen
  // becomes active and opens fully, the way a product page reveals itself
  const io = new IntersectionObserver((entries) => {
    if (Date.now() < navLock) return;
    entries.forEach((en) => {
      if (!en.isIntersecting) return;
      const idx = scenes.indexOf(en.target);
      if (idx !== cur) show(idx, maxStep(idx));
    });
  }, { root: $('deck'), rootMargin: '-50% 0px -50% 0px', threshold: 0 });
  scenes.forEach((s) => io.observe(s));

  listen((msg) => {
    if (!msg || msg.type !== 'cmd') return;
    if (msg.cmd === 'next') next();
    else if (msg.cmd === 'prev') prev();
    else if (msg.cmd === 'reset') { timerStart = Date.now(); post({ type: 'state', i: cur, s: step, timerStart }); }
    else if (msg.cmd === 'hello') post({ type: 'state', i: cur, s: step, timerStart });
  });

  window.addEventListener('keydown', (e) => {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    const k = e.key;
    if (['ArrowRight', 'ArrowDown', 'PageDown', ' ', 'Enter'].includes(k)) { e.preventDefault(); next(); }
    else if (['ArrowLeft', 'ArrowUp', 'PageUp', 'Backspace'].includes(k)) { e.preventDefault(); prev(); }
    else if (k === 'Home') goTo(0, 0, true);
    else if (k === 'End') goTo(N - 1, 0, true);
    else if (k === 'f' || k === 'F') toggleFS();
    else if (k === 'l' || k === 'L') setLang(lang === 'tr' ? 'en' : 'tr');
    else if (k === 'n' || k === 'N') { $('notesPanel').hidden = !$('notesPanel').hidden; updateNotes(); }
    else if (k === 'p' || k === 'P') openPresenter();
    else if (k === 'b' || k === 'B' || k === '.') $('blackout').classList.toggle('on');
    else if (k === 't' || k === 'T') { timerStart = Date.now(); updateNotes(); post({ type: 'state', i: cur, s: step, timerStart }); }
    else if (k === '?' || k === 'h' || k === 'H') $('help').hidden = !$('help').hidden;
    else if (k === 'Escape') { $('help').hidden = true; $('blackout').classList.remove('on'); }
  });
  $('help').addEventListener('click', () => { $('help').hidden = true; });
  $('prevBtn').addEventListener('click', prev);
  $('nextBtn').addEventListener('click', next);
  $('langBtn').addEventListener('click', () => setLang(lang === 'tr' ? 'en' : 'tr'));

  // Hide the arrows, language switch and cursor after a pause -- for mouse users only.
  // A touch screen sends no mousemove to bring them back, so there they always stay.
  const COARSE = window.matchMedia && matchMedia('(hover: none), (pointer: coarse)').matches;
  let idleT = 0;
  const wake = () => {
    document.body.classList.remove('idle'); clearTimeout(idleT);
    if (!COARSE) idleT = setTimeout(() => document.body.classList.add('idle'), 2500);
  };
  window.addEventListener('mousemove', (e) => { if (!(e.sourceCapabilities && e.sourceCapabilities.firesTouchEvents)) wake(); });
  window.addEventListener('pointerdown', (e) => {
    if (e.pointerType === 'mouse') wake();
    else { clearTimeout(idleT); document.body.classList.remove('idle'); }   // touch or pen: keep controls
  });
  wake();

  let rT = 0;
  window.addEventListener('resize', () => {
    clearTimeout(rT);
    rT = setTimeout(() => { const hk = H[scenes[cur].id]; if (hk && hk.redraw) hk.redraw(step); }, 150);
  });
  setInterval(() => { if (!$('notesPanel').hidden) updateNotes(); }, 1000);
})();
